// #region Remote File Provider

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖remotefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Remote%20File%20Provider)
// Remote file storage provider backed by a REST API.

/**
 * Creates a file provider factory that uploads and downloads files from a remote server.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖remotefileprovider🛠️createremotefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Remote%20File%20Provider/d/i/createRemoteFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖remotefileprovider🪨createremotefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Remote%20File%20Provider/d/i/createRemoteFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖remotefileprovider🪨createremotefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Remote%20File%20Provider/d/i/createRemoteFileProvider)
 **/
export function createRemoteFileProvider(config: RemoteFileProviderConfig): FileProviderFactory {
  return async (kitId: string): Promise<FileProvider> => {
    const getUrl = (kitId: string, fileId: string, path: string): string => {
      return `${config.baseUrl}/kits/${kitId}/files/${fileId}`;
    };

    const headers = {
      ...config.headers,
    };

    return {
      upload: async (kitId, fileId, path, blob) => {
        const formData = new FormData();
        formData.append("file", blob, path);

        const response = await fetch(getUrl(kitId, fileId, path), {
          method: "POST",
          headers,
          body: formData,
        });

        if (!response.ok) {
          throw new Error(`Remote upload failed: ${response.statusText}`);
        }

        const result = await response.json();
        return result.url || getUrl(kitId, fileId, path);
      },

      download: async (kitId, fileId, path) => {
        const response = await fetch(getUrl(kitId, fileId, path), {
          method: "GET",
          headers,
        });

        if (!response.ok) {
          throw new Error(`Remote download failed: ${response.statusText}`);
        }

        const blob = await response.blob();
        return blob;
      },

      delete: async (kitId, fileId, path) => {
        const response = await fetch(getUrl(kitId, fileId, path), {
          method: "DELETE",
          headers,
        });
        if (!response.ok) {
          throw new Error(`Remote delete failed: ${response.statusText}`);
        }
      },

      getUrl: (kitId, fileId, path) => {
        return getUrl(kitId, fileId, path);
      },
    };
  };
}

