/**
 * Selector returning kit import operations from background operations.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖machine🔖sketchpadmachine🔖sketchpadselectors🪨selectkitimportoperations](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Machine/s/Sketchpad%20Machine/s/Sketchpad%20Selectors/d/i/selectKitImportOperations)
 **/
export const selectKitImportOperations = (state: { context: SketchpadContext }) => {
  const ops = state.context.backgroundOperations;
  return Object.entries(ops)
    .filter(([_, op]) => op.type.startsWith("kit-import:"))
    .map(([id, op]) => ({
      operationId: id,
      kitName: op.type.replace("kit-import:", ""),
      status: op.status,
      error: op.error,
    }));
};

