    setSections((prev) => {
      const currentSections = prev[panelKey] ?? [];
      const nextSections = currentSections.filter((section) => section.id !== sectionId);
      if (nextSections.length === currentSections.length) return prev;
      return { ...prev, [panelKey]: nextSections };
    });
  }, []);

