        console.error("Failed to load GoldenLayout:", error);
      }
    };

    loadGoldenLayout();

    return () => {
      clearHoveredSplitter();
      if (containerRef.current && handleSplitterHoverRef.current && handleSplitterLeaveRef.current) {
