// React Router integration with scope providers and route-based app switching.

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖approuter🪨scopewrapper](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/App%20Router/d/i/ScopeWrapper)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖approuter🪨scopewrapper](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/App%20Router/d/i/ScopeWrapper)
 * ScopeWrapper holds the data fields for a ScopeWrapper record.
 **/
const ScopeWrapper: FC<{ ScopeProvider: ComponentType<{ guid: string; children: ReactNode }>; paramName: string; children: ReactNode }> = ({ ScopeProvider, paramName, children }) => {
  const params = useParams();
  const guid = params[paramName];
  if (!guid) return <>{children}</>;
  return <ScopeProvider guid={guid}>{children}</ScopeProvider>;
};

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖approuter🪨approuter](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/App%20Router/d/i/AppRouter)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖approuter🪨approuter](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/App%20Router/d/i/AppRouter)
 * AppRouter holds the data fields for a AppRouter record.
 **/
const AppRouter: FC = () => {
  const [appsInitialized, setAppsInitialized] = useState(false);

  useEffect(() => {
    if (!appsInitialized) {
      appRegistry.initialize().then(() => setAppsInitialized(true));
    }
  }, [appsInitialized]);

  const apps = useMemo(() => {
    if (!appsInitialized) return [];
    const sortedApps = appRegistry.getAllApps();
    return sortedApps;
  }, [appsInitialized]);

  const buildRoute = (app: AppRegistration, segments: RouteSegment[], index: number = 0): ReactNode => {
    if (index >= segments.length) {
      return <Route key={app.id} path="*" element={<app.component />} />;
    }

    const segment = segments[index];
    const paramName = segment.paramName;
    const ScopeProvider = segment.scopeProvider;
    const isLast = index === segments.length - 1;
    const routePath = index === 0 && !segment.path.startsWith("/") ? `/${segment.path}` : segment.path;

    if (ScopeProvider && paramName) {
      return (
        <Route
          key={`${app.id}-${index}`}
          path={routePath}
          element={
            <ScopeWrapper ScopeProvider={ScopeProvider} paramName={paramName}>
              {isLast ? <app.component /> : <Outlet />}
            </ScopeWrapper>
          }
        >
          {!isLast && buildRoute(app, segments, index + 1)}
        </Route>
      );
    }
    return (
      <Route key={`${app.id}-${index}`} path={routePath} element={isLast ? <app.component /> : <Outlet />}>
        {!isLast && buildRoute(app, segments, index + 1)}
      </Route>
    );
  };

  if (!appsInitialized) {
    return <div className="h-screen w-screen" />;
  }

  return (
    <Routes>
      {apps.map((app) => {
        if (app.routeSegments.length === 0) {
          const paths = app.additionalPaths || [];
          return [<Route key={`${app.id}-root`} path="/" element={<app.component />} />, ...paths.map((path) => <Route key={`${app.id}-${path}`} path={path} element={<app.component />} />)];
        }
        return buildRoute(app, app.routeSegments);
      })}
    </Routes>
  );
};

