// #region Composite File Provider

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖compositefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Composite%20File%20Provider)
// Composite file storage provider that delegates to multiple underlying providers.

/**
 * Creates a file provider factory that composes memory, local, and remote providers.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖compositefileprovider🛠️createcompositefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Composite%20File%20Provider/d/i/createCompositeFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖compositefileprovider🪨createcompositefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Composite%20File%20Provider/d/i/createCompositeFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖compositefileprovider🪨createcompositefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Composite%20File%20Provider/d/i/createCompositeFileProvider)
 **/
export function createCompositeFileProvider(config: CompositeFileProviderConfig): FileProviderFactory {
  return async (kitId: string): Promise<FileProvider> => {
    const providers: FileProvider[] = [];

    if (config.memory) {
      const memoryProvider = await createMemoryFileProvider()(kitId);
      providers.push(memoryProvider);
    }

    if (config.local) {
      const localConfig = typeof config.local === "object" ? config.local : undefined;
      const localProvider = await createLocalFileProvider(localConfig)(kitId);
      providers.push(localProvider);
    }

    if (config.remote) {
      const remoteProvider = await createRemoteFileProvider(config.remote)(kitId);
      providers.push(remoteProvider);
    }

    if (providers.length === 0) {
      throw new Error("At least one provider must be configured");
    }

    return {
      upload: async (kitId, fileId, path, blob) => {
        const results = await Promise.allSettled(providers.map((p) => p.upload(kitId, fileId, path, blob)));

        const successful = results.filter((r) => r.status === "fulfilled");
        if (successful.length === 0) {
          throw new Error(`All providers failed to upload file ${path}`);
        }

        const lastSuccessful = results.reverse().find((r) => r.status === "fulfilled") as PromiseFulfilledResult<string>;
        return lastSuccessful.value;
      },

      download: async (kitId, fileId, path) => {
        for (const provider of providers) {
          try {
            return await provider.download(kitId, fileId, path);
          } catch (error) {
            console.warn(`Provider failed to download ${path}, trying next:`, error);
          }
        }
        throw new Error(`All providers failed to download file ${path}`);
      },

      delete: async (kitId, fileId, path) => {
        await Promise.allSettled(providers.map((p) => p.delete(kitId, fileId, path)));
      },

      getUrl: (kitId, fileId, path) => {
        return providers[providers.length - 1].getUrl(kitId, fileId, path);
      },
    };
  };
}

