  const designScope = useDesignScope();
  const kit = useKitSnapshot();
  if (!kit || !designScope) return EMPTY_CONNECTIONS;
  const design = kit.designs?.find((d) => d.guid === designScope.guid);
  return design?.connections ?? EMPTY_CONNECTIONS;
}

