// [👤compose📚js🗃️sketchpad💻sketchpad🔖conceptfilter](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/ConceptFilter)
// Filter component for narrowing results by architectural concepts.

/**
 * Component rendering a concept filter strip with toggle actions.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖conceptfilter🪨conceptfilter](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/ConceptFilter/d/i/ConceptFilter)
 **/
export const ConceptFilter: FC<{ allConcepts: string[]; paramName?: string }> = ({ allConcepts, paramName = "concepts" }) => {
  const [searchParams, setSearchParams] = useSearchParams();
  const selectedConcepts = paramName === "c" ? searchParams.getAll("c") : searchParams.get(paramName)?.split(",").filter(Boolean) || [];

  const toggleConcept = useCallback(
    (concept: string) => {
      const newParams = new URLSearchParams(searchParams);
      if (paramName === "c") {
        const currentConcepts = newParams.getAll("c");
        if (currentConcepts.includes(concept)) {
          newParams.delete("c");
          currentConcepts.filter((c) => c !== concept).forEach((c) => newParams.append("c", c));
        } else {
          newParams.append("c", concept);
        }
      } else {
        const currentConcepts = newParams.get(paramName)?.split(",").filter(Boolean) || [];
        if (currentConcepts.includes(concept)) {
          const updated = currentConcepts.filter((c) => c !== concept);
          if (updated.length > 0) {
            newParams.set(paramName, updated.join(","));
            newParams.delete(paramName);
          }
        } else {
          newParams.set(paramName, [...currentConcepts, concept].join(","));
        }
      }
      setSearchParams(newParams);
    },
    [searchParams, setSearchParams, paramName],
  );

  if (allConcepts.length === 0) return null;

  return (
    <Strip
      id="compose.sketchpad.filter.concepts"
      items={allConcepts.map((concept) => ({
        key: concept,
        content: <Action onClick={() => toggleConcept(concept)} id={`compose.sketchpad.filter.concept.${concept}`} text={concept} className={selectedConcepts.includes(concept) ? "bg-active-base" : ""} />,
      }))}
    />
  );
};

