// [👤compose📚js🗃️sketchpad💻sketchpad🔖hotkeys](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Hotkeys)
// Keyboard shortcut hook with configurable hotkey overrides.

/**
 * Hook binding a keyboard shortcut with optional override resolution.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖hotkeys🛠️usehotkeys](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Hotkeys/d/i/useHotkeys)
 **/
export function useHotkeys(hotkeyOrPath: string, callback: () => void, options?: { enableOnFormTags?: boolean }, deps?: React.DependencyList) {
  const hotkeyOverrides = useSketchpad((s) => s.hotkeyOverrides) as Record<string, string> | undefined;
  const translatedHotkey = useHotkey(hotkeyOrPath);

  useCommandHotkey(hotkeyOrPath, callback, options || {}, deps || [], {
    overrides: hotkeyOverrides,
    translatedHotkey,
  });
}

