    (windowTypeId: string, direction: "horizontal" | "vertical", splitterElement: HTMLElement) => {
      if (!layoutRef.current) {
        return;
      }
      if (!splitterElement) {
        return;
      }

      const windowType = windowConfig.windowKinds.find((wt) => wt.id === windowTypeId);
      if (!windowType) {
        return;
      }

      const newItemConfig = {
        type: "stack",
        content: [
          {
            type: "component",
            componentName: windowTypeId,
