// In-memory file storage provider for temporary or test scenarios.

/**
 * Creates a file provider factory that stores files in memory.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖memoryfileprovider🛠️creatememoryfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Memory%20File%20Provider/d/i/createMemoryFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖memoryfileprovider🪨creatememoryfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Memory%20File%20Provider/d/i/createMemoryFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖memoryfileprovider🪨creatememoryfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Memory%20File%20Provider/d/i/createMemoryFileProvider)
 **/
export function createMemoryFileProvider(config?: MemoryFileProviderConfig): FileProviderFactory {
  const storage = new Map<string, Blob>();

  return async (kitId: string): Promise<FileProvider> => {
    const getKey = (kitId: string, fileId: string, path: string): string => {
      return `${kitId}/${fileId}/${path}`;
    };

    return {
      upload: async (kitId, fileId, path, blob) => {
        const key = getKey(kitId, fileId, path);
        storage.set(key, blob);
        return `memory://${key}`;
      },

      download: async (kitId, fileId, path) => {
        const key = getKey(kitId, fileId, path);
        const blob = storage.get(key);

        if (!blob) {
          throw new Error(`File not found in memory: ${key}`);
        }

        return blob;
      },

      delete: async (kitId, fileId, path) => {
        const key = getKey(kitId, fileId, path);
        storage.delete(key);
        return `memory://${getKey(kitId, fileId, path)}`;
      },

      getUrl: (kitId, fileId, path) => {
        return `memory://${getKey(kitId, fileId, path)}`;
      },
    };
  };
}

