// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖localfileproviderindexeddb](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Local%20File%20Provider%20(IndexedDB))
// Browser-local file storage provider backed by IndexedDB.

/**
 * Creates a file provider factory that persists files in IndexedDB.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖fileprovider🔖localfileproviderindexeddb🛠️createlocalfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/File%20Provider/s/Local%20File%20Provider%20(IndexedDB)/d/i/createLocalFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖fileprovider🔖localfileproviderindexeddb🪨createlocalfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/File%20Provider/s/Local%20File%20Provider%20(IndexedDB)/d/i/createLocalFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖localfileproviderindexeddb🪨createlocalfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Local%20File%20Provider%20(IndexedDB)/d/i/createLocalFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖localfileproviderindexeddb🪨createlocalfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Local%20File%20Provider%20(IndexedDB)/d/i/createLocalFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖localfileproviderindexeddb🪨createlocalfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Local%20File%20Provider%20(IndexedDB)/d/i/createLocalFileProvider)
 **/
export function createLocalFileProvider(config?: LocalFileProviderConfig): FileProviderFactory {
  const dbName = config?.dbName || "compose-files";
  const storeName = config?.storeName || "files";

  const openDB = (): Promise<IDBDatabase> => {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(dbName, 1);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(storeName)) {
          db.createObjectStore(storeName);
        }
      };
    });
  };

  return async (kitId: string): Promise<FileProvider> => {
    const getKey = (kitId: string, fileId: string, path: string): string => {
      return `${kitId}/${fileId}/${path}`;
    };

    return {
      upload: async (kitId, fileId, path, blob) => {
        const key = getKey(kitId, fileId, path);
        const db = await openDB();

        return new Promise<string>((resolve, reject) => {
          const transaction = db.transaction([storeName], "readwrite");
          const store = transaction.objectStore(storeName);
          const request = store.put(blob, key);

          request.onsuccess = () => {
            resolve(`local://${key}`);
          };
          request.onerror = () => reject(request.error);

          transaction.oncomplete = () => db.close();
        });
      },

      download: async (kitId, fileId, path) => {
        const key = getKey(kitId, fileId, path);
        const db = await openDB();

        return new Promise<Blob>((resolve, reject) => {
          const transaction = db.transaction([storeName], "readonly");
          const store = transaction.objectStore(storeName);
          const request = store.get(key);

          request.onsuccess = () => {
            const blob = request.result;
            if (!blob) {
              reject(new Error(`File not found in IndexedDB: ${key}`));
            } else {
              resolve(blob);
            }
          };
          request.onerror = () => reject(request.error);

          transaction.oncomplete = () => db.close();
        });
      },

      delete: async (kitId, fileId, path) => {
        const key = getKey(kitId, fileId, path);
        const db = await openDB();

        return new Promise<void>((resolve, reject) => {
          const transaction = db.transaction([storeName], "readwrite");
          const store = transaction.objectStore(storeName);
          const request = store.delete(key);

          request.onsuccess = () => {
            resolve();
          };
          request.onerror = () => reject(request.error);

          transaction.oncomplete = () => db.close();
        });
      },

      getUrl: (kitId, fileId, path) => {
        return `local://${kitId}/${fileId}/${path}`;
      },
    };
  };
}

// #endregion Local File Provider (IndexedDB)

// #region Remote File Provider

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖remotefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Remote%20File%20Provider)
// Remote file storage provider backed by a REST API.

/**
 * Creates a file provider factory that uploads and downloads files from a remote server.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖remotefileprovider🛠️createremotefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Remote%20File%20Provider/d/i/createRemoteFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖remotefileprovider🪨createremotefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Remote%20File%20Provider/d/i/createRemoteFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖remotefileprovider🪨createremotefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Remote%20File%20Provider/d/i/createRemoteFileProvider)
 **/
export function createRemoteFileProvider(config: RemoteFileProviderConfig): FileProviderFactory {
  return async (kitId: string): Promise<FileProvider> => {
    const getUrl = (kitId: string, fileId: string, path: string): string => {
      return `${config.baseUrl}/kits/${kitId}/files/${fileId}`;
    };

    const headers = {
      ...config.headers,
    };

    return {
      upload: async (kitId, fileId, path, blob) => {
        const formData = new FormData();
        formData.append("file", blob, path);

        const response = await fetch(getUrl(kitId, fileId, path), {
          method: "POST",
          headers,
          body: formData,
        });

        if (!response.ok) {
          throw new Error(`Remote upload failed: ${response.statusText}`);
        }

        const result = await response.json();
        return result.url || getUrl(kitId, fileId, path);
      },

      download: async (kitId, fileId, path) => {
        const response = await fetch(getUrl(kitId, fileId, path), {
          method: "GET",
          headers,
        });

        if (!response.ok) {
          throw new Error(`Remote download failed: ${response.statusText}`);
        }

        const blob = await response.blob();
        return blob;
      },

      delete: async (kitId, fileId, path) => {
        const response = await fetch(getUrl(kitId, fileId, path), {
          method: "DELETE",
          headers,
        });
        if (!response.ok) {
          throw new Error(`Remote delete failed: ${response.statusText}`);
        }
      },

      getUrl: (kitId, fileId, path) => {
        return getUrl(kitId, fileId, path);
      },
    };
  };
}

// #endregion Remote File Provider

// #region Composite File Provider

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖compositefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Composite%20File%20Provider)
// Composite file storage provider that delegates to multiple underlying providers.

/**
 * Creates a file provider factory that composes memory, local, and remote providers.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖compositefileprovider🛠️createcompositefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Composite%20File%20Provider/d/i/createCompositeFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖compositefileprovider🪨createcompositefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Composite%20File%20Provider/d/i/createCompositeFileProvider)
 *[👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖compositefileprovider🪨createcompositefileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Composite%20File%20Provider/d/i/createCompositeFileProvider)
 **/
export function createCompositeFileProvider(config: CompositeFileProviderConfig): FileProviderFactory {
  return async (kitId: string): Promise<FileProvider> => {
    const providers: FileProvider[] = [];

    if (config.memory) {
      const memoryProvider = await createMemoryFileProvider()(kitId);
      providers.push(memoryProvider);
    }

    if (config.local) {
      const localConfig = typeof config.local === "object" ? config.local : undefined;
      const localProvider = await createLocalFileProvider(localConfig)(kitId);
      providers.push(localProvider);
    }

    if (config.remote) {
      const remoteProvider = await createRemoteFileProvider(config.remote)(kitId);
      providers.push(remoteProvider);
    }

    if (providers.length === 0) {
      throw new Error("At least one provider must be configured");
    }

    return {
      upload: async (kitId, fileId, path, blob) => {
        const results = await Promise.allSettled(providers.map((p) => p.upload(kitId, fileId, path, blob)));

        const successful = results.filter((r) => r.status === "fulfilled");
        if (successful.length === 0) {
          throw new Error(`All providers failed to upload file ${path}`);
        }

        const lastSuccessful = results.reverse().find((r) => r.status === "fulfilled") as PromiseFulfilledResult<string>;
        return lastSuccessful.value;
      },

      download: async (kitId, fileId, path) => {
        for (const provider of providers) {
          try {
            return await provider.download(kitId, fileId, path);
          } catch (error) {
            console.warn(`Provider failed to download ${path}, trying next:`, error);
          }
        }
        throw new Error(`All providers failed to download file ${path}`);
      },

      delete: async (kitId, fileId, path) => {
        await Promise.allSettled(providers.map((p) => p.delete(kitId, fileId, path)));
      },

      getUrl: (kitId, fileId, path) => {
        return providers[providers.length - 1].getUrl(kitId, fileId, path);
      },
    };
  };
}

