  "compose.kit.addFiles": (context: KitCommandContext, foldersToAdd: Folder[], filesToAdd: { file: ComposeFile; blob?: Blob }[]): KitCommandResult => {
    const composeFiles: ComposeFile[] = [];
    const files: File[] = [];
    for (const { file, blob } of filesToAdd) {
      composeFiles.push(file);
      if (blob) files.push(new File([blob], file.name));
