/**
 * Hook returning shallow kit data for all kits with reactive updates.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️usekitshallows](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/useKitShallows)
 **/
export function useKitShallows(): KitShallow[] {
  const store = useSketchpadStore();
  return useSyncExternalStore(
    (onStoreChange) => {
      const unsubscribeCreated = store.onKitCreated(onStoreChange);
      const unsubscribeDeleted = store.onKitDeleted(onStoreChange);
      const unsubscribers = store.kitShallows().map((kitShallow) => {
        const kitStore = store.kit(kitShallow.guid);
        return kitStore.onChanged((cb: () => void) => {
          cb();
          onStoreChange();
          return () => {};
        });
      });
      return () => {
        unsubscribeCreated();
        unsubscribeDeleted();
        unsubscribers.forEach((unsub) => unsub());
      };
    },
    () => store.kitShallows(),
  );
}

/**
 * Hook returning whether a kit with the given guid exists.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️usehaskit](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/useHasKit)
 **/
export function useHasKit(kitGuid: string): boolean {
  const store = useSketchpadStore();
  return useSyncExternalStore(
    (onStoreChange) => {
      const unsubscribeCreated = store.onKitCreated(onStoreChange);
      const unsubscribeDeleted = store.onKitDeleted(onStoreChange);
      return () => {
        unsubscribeCreated();
        unsubscribeDeleted();
      };
    },
    () => store.hasKit(kitGuid),
  );
}

/**
 * Hook returning the persistence kind of a kit.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️usekitkind](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/useKitKind)
 **/
export function useKitKind(kitGuid: string): "temporary" | "local" | "remote" | undefined {
  const store = useSketchpadStore();
  const hasKit = useHasKit(kitGuid);
  return useSyncExternalStore(
    (onStoreChange) => {
      if (!hasKit) return () => {};
      const kitStore = store.kit(kitGuid);
      return kitStore.onChanged((cb: () => void) => {
        cb();
        onStoreChange();
        return () => {};
      });
    },
    () => {
      if (!hasKit) return undefined;
      const kitStore = store.kit(kitGuid);
      if (kitStore.isLocallyPersisted && kitStore.isRemotelySynced) return "remote";
      if (kitStore.isLocallyPersisted) return "local";
      return "temporary";
    },
  );
}

/**
 * Hook returning a callback to get the persistence kind of any kit.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️usegetkitkind](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/useGetKitKind)
 **/
export function useGetKitKind(): (kitGuid: string) => "temporary" | "local" | "remote" | undefined {
  const store = useSketchpadStore();
  return useCallback(
    (kitGuid: string) => {
      if (!store.hasKit(kitGuid)) return undefined;
      const kitStore = store.kit(kitGuid);
      if (kitStore.isLocallyPersisted && kitStore.isRemotelySynced) return "remote";
      if (kitStore.isLocallyPersisted) return "local";
      return "temporary";
    },
    [store],
  );
}

/**
 * Hook returning kit shallows filtered by persistence kind.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️usefilteredkitshallows](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/useFilteredKitShallows)
 **/
export function useFilteredKitShallows(kind?: "temporary" | "local" | "remote"): KitShallow[] {
  const store = useSketchpadStore();
  const allKits = useKitShallows();
  return useMemo(() => {
    if (!kind) return allKits;
    return allKits.filter((k) => {
      const ks = store.kit(k.guid);
      const kKind = ks.isLocallyPersisted && ks.isRemotelySynced ? "remote" : ks.isLocallyPersisted ? "local" : "temporary";
      return kKind === kind;
    });
  }, [allKits, kind, store]);
}

