    "[&_[data-slot='property-row']]:min-h-[24px]",
    "[&_[data-slot='property-row']]:grid-cols-[96px_minmax(0,1fr)]",
    "[&_[data-slot='property-row']]:gap-x-[8px]",
    "[&_[data-slot='property-label']]:min-w-0",
    "[&_[data-slot='property-label']]:px-0",
    "[&_[data-slot='property-label']]:text-xs",
    "[&_[data-slot='property-label']]:font-normal",
    "[&_[data-slot='input']]:!h-[22px]",
    "[&_[data-slot='input']]:rounded-[3px]",
    "[&_[data-slot='input']]:px-[6px]",
    "[&_[data-slot='input']]:text-xs",
    "[&_[data-slot='select-trigger']]:!h-[22px]",
    "[&_[data-slot='select-trigger']]:w-full",
    "[&_[data-slot='select-trigger']]:rounded-[3px]",
    "[&_[data-slot='select-trigger']]:px-[6px]",
    "[&_[data-slot='select-trigger']]:text-xs",
    "[&_[data-slot='select-trigger']_svg]:size-[12px]",
    "[&_[data-slot='stepper-group']]:h-[22px]",
    "[&_[data-slot='stepper-group']]:w-[100px]",
    "[&_[data-slot='stepper-group']]:rounded-[3px]",
    "[&_[data-slot='stepper-minus']]:h-[22px]",
    "[&_[data-slot='stepper-minus']]:w-[22px]",
    "[&_[data-slot='stepper-plus']]:h-[22px]",
    "[&_[data-slot='stepper-plus']]:w-[22px]",
    "[&_[data-slot='stepper-group']_[data-slot='input']]:!h-[22px]",
    "[&_[data-slot='stepper-group']_[data-slot='input']]:!w-[56px]",
    "[&_[data-slot='stepper-group']_[data-slot='input']]:!min-w-[56px]",
    "[&_[data-slot='stepper-group']_[data-slot='input']]:!px-0",
    "[&_[data-slot='slider-row']]:items-center",
    "[&_[data-slot='slider-row']]:gap-x-[8px]",
    "[&_[data-slot='slider-value']]:w-[28px]",
    "[&_[data-slot='slider-value']]:text-right",
    "[&_[data-slot='slider-row']_[data-slot='input']]:!px-0",
    "[&_[data-slot='slider-row']_[data-slot='input']]:!w-[28px]",
    "[&_[data-slot='slider-row']_[data-slot='input']]:!min-w-[28px]",
    "[&_[data-slot='button-group-item']]:h-medium",
    "[&_[data-slot='textarea']]:text-xs",
    "[&_[data-slot='textarea']]:rounded-[3px]",
    "[&_[data-slot='textarea']]:px-[6px]",
    "[&_[data-slot='textarea']]:py-[3px]",
    "[&_[data-slot='textarea']]:min-h-[44px]",
    "[&_[role='combobox']]:!h-[22px]",
    "[&_[role='combobox']]:rounded-[3px]",
    "[&_[role='combobox']]:px-[6px]",
    "[&_[role='combobox']]:text-xs",
    "[&_[role='combobox']_svg]:size-[12px]",
  ].join(" ");

  const [activeDragId, setActiveDragId] = useState<string | null>(null);
  const [activeDragData, setActiveDragData] = useState<any>(null);
  const [activeToolbarGroup, setActiveToolbarGroup] = useState<string | null>(null);

  const toolbarGroups = useMemo(() => {
    const groups: Record<string, PanelSection[]> = {};
    toolbarSections.forEach((section) => {
      const gid = section.toolbarGroup?.id;
      if (gid) {
        if (!groups[gid]) groups[gid] = [];
        groups[gid].push(section);
      }
    });

    Object.keys(groups).forEach((key) => {
      groups[key].sort((a, b) => (a.toolbarGroup?.order ?? 0) - (b.toolbarGroup?.order ?? 0));
    });
    return groups;
  }, [toolbarSections]);

  useEffect(() => {
    const groupOrder = ["hand", "selection", "filter", "create", "view", "actions"];
    const firstGroup = groupOrder.find((g) => g !== "hand" && toolbarGroups[g]);
    setActiveToolbarGroup((prev) => (prev === null || (prev !== null && !toolbarGroups[prev]) ? (firstGroup ?? null) : prev));
  }, [toolbarGroups]);

  const toolbarGroupsRef = useRef(toolbarGroups);
  toolbarGroupsRef.current = toolbarGroups;
  const toggleToolbarGroup = useCallback((id: string) => {
    setActiveToolbarGroup((prev) => {
      const next = prev === id ? null : id;
      if (next) {
        queueMicrotask(() => {
          const groups = toolbarGroupsRef.current;
          if (groups[next]) {
            for (const section of groups[next]) {
              section.toolbarGroup?.onActivate?.();
            }
          }
        });
      }
      return next;
    });
  }, []);

  const [activeSubToolByGroup, setActiveSubToolByGroup] = useState<Record<string, string>>({});

  const setSubTool = useCallback((groupId: string, subToolId: string) => {
    setActiveSubToolByGroup((prev) => ({ ...prev, [groupId]: subToolId }));
    setActiveToolbarGroup(groupId);
  }, []);

  const getGroupIcon = useCallback((groupId: string) => {
    switch (groupId) {
      case "hand":
        return <HandIcon className="size-tiny" />;
      case "selection":
        return <MousePointerIcon className="size-tiny" />;
      case "filter":
        return <SearchIcon className="size-tiny" />;
      case "create":
        return <AddIcon className="size-tiny" />;
      case "view":
        return <LayoutIcon className="size-tiny" />;
      case "actions":
        return <MoreHorizontalIcon className="size-tiny" />;
      default:
        return <FocusIcon className="size-tiny" />;
    }
  }, []);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8, // 8px of movement required before drag starts
      },
    }),
  );

  const customCollisionDetection = useCallback((args: any) => {
    const pointerCollisions = pointerWithin(args);

    if (pointerCollisions.length > 0) {
      return pointerCollisions;
    }

    const rectCollisions = rectIntersection(args);

    if (rectCollisions.length > 0) {
      return rectCollisions;
    }

    const centerCollisions = closestCenter(args);

    if (centerCollisions && centerCollisions.length > 0) {
      return centerCollisions;
    }
    return [];
  }, []);
  const kitShallows = useKitShallows();
  const getTypeOrDesignName = useCallback(() => {
    if (!activeDragData) return null;
    if (activeDragData.type === "type") {
      const kitId = activeDragData.typeGuid?.split("-")[0];
      const kit = kitShallows.find((k) => k.guid.startsWith(kitId));
      const type = kit?.types?.find((t: any) => typeof t === "object" && t.guid === activeDragData.typeGuid) as any;
      return type?.name || "Type";
    } else if (activeDragData.type === "design") {
      const kitId = activeDragData.designGuid?.split("-")[0];
      const kit = kitShallows.find((k) => k.guid.startsWith(kitId));
      const design = kit?.designs?.find((d: any) => typeof d === "object" && d.guid === activeDragData.designGuid) as any;
      return design?.name || "Design";
    }
    return null;
  }, [activeDragData, kitShallows]);
  return (
    <TutorialProvider store={tutorialStore}>
      <GlobalFooterItems />
      <DndContext
        sensors={sensors}
        collisionDetection={customCollisionDetection}
        onDragStart={(event) => {
          setActiveDragId(event.active.id as string);
          setActiveDragData(event.active.data.current);

          sketchpadCommands.setActiveInteraction("compose.sketchpad.drag", "dragging");
        }}
        onDragEnd={(event) => {
          setActiveDragId(null);
          setActiveDragData(null);

          sketchpadCommands.setActiveInteraction("compose.sketchpad.drag", undefined);

          const customEvent = new CustomEvent("design-drag-end", { detail: event });
          window.dispatchEvent(customEvent);
        }}
      >
        <LevelProvider level="base">
          <ToolbarScopeWrapper>
            <LayoutComponent
              className="bg-base text-foreground relative border"
              navbar={<Navbar items={navbarItems} />}
              footer={
                <Footer
                  items={footerItems.map((item) => ({
                    id: item.id,
                    icon: item.icon,
                    text: item.text,
                    content: item.content,
                    order: item.order,
                    onClick: item.onClick,
                  }))}
                  isVisible={isFooterExpanded || !isFullscreen}
                />
              }
              bottomPanel={
                consoleSections.length > 0
                  ? {
                      visible: true,
                      size: panelSizes.consoleHeight,
                      onSizeChange: (size: number) => sketchpadCommands.setPanelSize("compose.sketchpad", "consoleHeight", size),
                      sections: consoleSections,
                      panelKey: "console",
                    }
                  : undefined
              }
              leftSidePanel={
                leftSidePanelTabs.length > 0 && panelVisibility.leftSidePanel
                  ? {
                      position: "left" as const,
                      visible: true,
                      size: panelSizes.leftSidePanelWidth,
                      onSizeChange: (size: number) => sketchpadCommands.setPanelSize("compose.sketchpad", "leftSidePanelWidth", size),
                      tabs: leftSidePanelTabs,
                      activeTabId: activeLeftTabId,
                      onActiveTabChange: setActiveLeftTabId,
                    }
                  : undefined
              }
              rightSidePanel={
                rightSidePanelTabs.length > 0 && panelVisibility.rightSidePanel
                  ? {
                      position: "right" as const,
                      visible: true,
                      size: panelSizes.rightSidePanelWidth,
                      onSizeChange: (size: number) => sketchpadCommands.setPanelSize("compose.sketchpad", "rightSidePanelWidth", size),
                      tabs: rightSidePanelTabs,
                      activeTabId: activeRightTabId,
                      onActiveTabChange: setActiveRightTabId,
                      minSize: 150,
                      maxSize: 500,
                      className: rightSidePanelElementSizingClassName,
                    }
                  : undefined
              }
              toolbar={
                panelVisibility.toolbar || appType === "type" || appType === "design" || appType === "feedback" || appType === "kit" || appType === "home" || appType === "quality" || appType === "docs" ? (
                  toolbarSections.length > 0 ? (
                    <div role="toolbar" id="compose.sketchpad.toolbar" className="absolute bottom-1.5 left-0 right-0 h-[40px] pointer-events-none px-2">
                      <div id="compose.sketchpad.toolbar.seam" className="absolute left-1/2 top-0 h-full w-0 -translate-x-1/2">
                        <div id="compose.sketchpad.toolbar.zone.tools" className="absolute right-[4px] top-0 h-full max-w-[calc(50vw-1rem)] pointer-events-auto">
                          <LevelProvider level="panel">
                            <ToolbarZone>
                              {["hand", "selection", "filter", "create", "view", "actions"].map((groupId) => {
                                if (!toolbarGroups[groupId]) return null;
                                const isActive = activeToolbarGroup === groupId;

                                if (groupId === "selection") {
                                  const activeSubToolId = activeSubToolByGroup[groupId] || toolbarGroups[groupId].find((s) => s.toolbarGroup?.subToolId)?.toolbarGroup?.subToolId;
                                  const uniqueSubTools = Array.from(new Set(toolbarGroups[groupId].map((s) => s.toolbarGroup?.subToolId).filter(Boolean))) as string[];
                                  if (uniqueSubTools.length === 0) {
                                    return (
                                      <Toggle
                                        key={groupId}
                                        kind="single"
                                        id={`compose.sketchpad.toolbar.group.${groupId}`}
                                        pressed={isActive}
                                        onPressedChange={() => toggleToolbarGroup(groupId)}
                                        icon={getGroupIcon(groupId)}
                                        text={i18n.t(`compose.sketchpad.toolbar.parent.${groupId}`)}
                                      />
                                    );
                                  }

                                  return (
                                    <Toggle
                                      key={groupId}
                                      kind="dropdown"
                                      id={`compose.sketchpad.toolbar.group.${groupId}`}
                                      value={activeSubToolId}
                                      pressed={isActive}
                                      onPressedChange={(pressed) => {
                                        setActiveToolbarGroup(pressed ? groupId : null);
                                      }}
                                      onValueChange={(val) => val && setSubTool(groupId, val)}
                                      dropdownSide="top"
                                      dropdownAlign="end"
                                      dropdownSideOffset={2}
                                      dropdownAvoidCollisions={false}
                                      dropdownInstant={true}
                                      dropdownContentClassName="w-[10.5rem] min-w-[10.5rem] p-0 overflow-hidden border transition-none"
                                      items={uniqueSubTools.map((subToolId) => {
                                        const section = toolbarGroups[groupId].find((s) => s.toolbarGroup?.subToolId === subToolId);
                                        return {
                                          value: subToolId,
                                          label: section?.toolbarGroup?.subToolIcon || <FocusIcon className="size-tiny" />,
                                          text: section?.toolbarGroup?.subToolLabelId ? i18n.t(section.toolbarGroup.subToolLabelId) : subToolId,
                                          id: `compose.sketchpad.toolbar.subtool.${subToolId}`,
                                        };
                                      })}
                                    />
                                  );
                                }

                                return (
                                  <Toggle
                                    key={groupId}
                                    kind="single"
                                    id={`compose.sketchpad.toolbar.group.${groupId}`}
                                    pressed={isActive}
                                    onPressedChange={() => toggleToolbarGroup(groupId)}
                                    icon={getGroupIcon(groupId)}
                                    text={i18n.t(`compose.sketchpad.toolbar.parent.${groupId}`)}
                                  />
                                );
                              })}
                            </ToolbarZone>
                          </LevelProvider>
                        </div>

                        {activeToolbarGroup && toolbarGroups[activeToolbarGroup] && (
                          <div id="compose.sketchpad.toolbar.zone.settings" className="absolute left-[4px] top-0 h-full max-w-[calc(50vw-1rem)] pointer-events-auto">
                            <LevelProvider level="panel">
                              <ToolbarZone className="flex-nowrap min-w-0">
                                <ToolbarScopeWrapper>
                                  {toolbarGroups[activeToolbarGroup]?.map((section) => {
                                    if (activeToolbarGroup === "selection") {
                                      const activeSubToolId = activeSubToolByGroup["selection"] || toolbarGroups["selection"].find((s) => s.toolbarGroup?.subToolId)?.toolbarGroup?.subToolId;
                                      const hasSelectionSubTools = toolbarGroups["selection"]?.some((s) => Boolean(s.toolbarGroup?.subToolId));
                                      if (hasSelectionSubTools && section.toolbarGroup?.subToolId !== activeSubToolId) return null;
                                    }
                                    return <ToolbarItem key={section.id}>{typeof section.content === "function" ? section.content() : section.content}</ToolbarItem>;
                                  })}
                                </ToolbarScopeWrapper>
                              </ToolbarZone>
                            </LevelProvider>
                          </div>
                        )}
                      </div>
                    </div>
                  ) : (
                    <div id="compose.sketchpad.toolbar" className="hidden" />
                  )
                ) : undefined
              }
              canvas={
                <div className="relative h-full w-full">
                  <AppRouter />
                </div>
              }
            />
          </ToolbarScopeWrapper>
        </LevelProvider>
        <DragOverlay>
          {activeDragId && activeDragData ? (
            <div className="cursor-grabbing">
              <div className="border border-element rounded-full w-small h-small flex items-center justify-center shadow-lg">
                <span className="text-small font-medium select-none">{getTypeOrDesignName()?.substring(0, 2).toUpperCase() || "?"}</span>
              </div>
            </div>
          ) : null}
        </DragOverlay>
      </DndContext>
    </TutorialProvider>
  );
};

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖sketchpadcomponents🪨sketchpadinteractionbridge](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Sketchpad%20Components/d/i/SketchpadInteractionBridge)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖sketchpadcomponents🪨sketchpadinteractionbridge](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Sketchpad%20Components/d/i/SketchpadInteractionBridge)
 * SketchpadInteractionBridge holds the data fields for a SketchpadInteractionBridge record.
 **/
const SketchpadInteractionBridge: FC<{ children: React.ReactNode }> = ({ children }) => {
  const sketchpadCommands = useSketchpadCommands();
  const activeInteraction = useActiveInteraction();

  const interactionCommands = useMemo(
    () => ({
      setActiveInteraction: (elementId?: string, interactionId?: string) => {
        sketchpadCommands.setActiveInteraction(elementId || "compose.interaction", interactionId);
      },
    }),
    [sketchpadCommands],
  );

  return (
    <InteractionProvider commands={interactionCommands} activeInteraction={activeInteraction}>
      {children}
    </InteractionProvider>
  );
};

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖sketchpadcomponents🪨globalnavigationbridge](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Sketchpad%20Components/d/i/GlobalNavigationBridge)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖sketchpadcomponents🪨globalnavigationbridge](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Sketchpad%20Components/d/i/GlobalNavigationBridge)
 * GlobalNavigationBridge holds the data fields for a GlobalNavigationBridge record.
 **/
const GlobalNavigationBridge: FC<{ children: React.ReactNode }> = ({ children }) => {
  const reactNavigate = useReactNavigate();

  useEffect(() => {
    if (typeof window !== "undefined") {
      (window as any).__COMPOSE_NAVIGATE__ = reactNavigate;
    }
    return () => {
      if (typeof window !== "undefined") {
        delete (window as any).__COMPOSE_NAVIGATE__;
      }
    };
  }, [reactNavigate]);

  return <>{children}</>;
};

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖sketchpadcomponents🪨sketchpadcontent](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Sketchpad%20Components/d/i/SketchpadContent)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖sketchpadcomponents🪨sketchpadcontent](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Sketchpad%20Components/d/i/SketchpadContent)
 * SketchpadContent holds the data fields for a SketchpadContent record.
 **/
const SketchpadContent: FC = () => {
  return <LayoutWrapper />;
};

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖sketchpadcomponents🪨sketchpad](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Sketchpad%20Components/d/i/Sketchpad)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖sketchpadcomponents🪨sketchpad](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Sketchpad%20Components/d/i/Sketchpad)
 * Sketchpad holds the data fields for a Sketchpad record.
 **/
const Sketchpad = ({
  id,
  store,
  kitStore,
  remote,
  persistenceFactory,
  onWindowEvents,
  initialState,
  importKitUrls,
  embedded,
}: {
  id?: string;
  store?: SketchpadStore;
  kitStore?: KitStore;
  remote?: RemoteProviders;
  persistenceFactory?: PersistenceFactory;
  onWindowEvents?: WindowEvents;
  initialState?: ExtendedInitialState;
  importKitUrls?: string[];
  embedded?: boolean;
}): React.JSX.Element => {
  const initialEntries = useMemo(() => {
    if (!embedded) return undefined;
    if (typeof window !== "undefined" && window.location) {
      return [window.location.pathname + window.location.search];
    }
    return ["/"];
  }, [embedded]);

  const routerContent = (
    <GlobalNavigationBridge>
      <SketchpadScopeProvider id={id} store={store} kitStore={kitStore} remote={remote} persistenceFactory={persistenceFactory} onWindowEvents={onWindowEvents} initialState={initialState} importKitUrls={importKitUrls}>
        <SketchpadInteractionBridge>
          <OriginProvider>
            <FocusProvider>
              <PanelSectionProvider>
                <SidePanelTabProvider>
                  <FooterItemProvider>
                    <DragDropProvider>
                      <SketchpadContent />
                    </DragDropProvider>
                  </FooterItemProvider>
                </SidePanelTabProvider>
              </PanelSectionProvider>
            </FocusProvider>
          </OriginProvider>
        </SketchpadInteractionBridge>
      </SketchpadScopeProvider>
    </GlobalNavigationBridge>
  );

  if (embedded) {
    return (
      <MemoryRouter initialEntries={initialEntries} unstable_useTransitions={false}>
        {routerContent}
      </MemoryRouter>
    );
  }

  return <BrowserRouter unstable_useTransitions={false}>{routerContent}</BrowserRouter>;
};

