  const [folderPath, setFolderPath] = useState<string | null>(null);
  const [kitStore, setKitStore] = useState<KitStore | undefined>(undefined);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    async function fetchUserId() {
      try {
