let createFolderKitStore: any = null;
type KitFolderAdapter = import("@compose/studio").KitFolderAdapter;
type KitStore = import("@compose/js/compose").KitStore;

const loadModules = async () => {
  console.log("[DEBUG] Loading @compose/studio...");
  const studio = await import("@compose/studio");
  createFolderKitStore = studio.createFolderKitStore;
  console.log("[DEBUG] @compose/studio loaded");

  console.log("[DEBUG] Loading @compose/sketchpad...");
  const sketchpad = await import("@compose/sketchpad");
  Sketchpad = sketchpad.Sketchpad;
  console.log("[DEBUG] @compose/sketchpad loaded");
};

const modulesReady = loadModules();

declare global {
  interface Window {
    windowControls: {
      minimize(): Promise<any>;
      maximize(): Promise<any>;
      close(): Promise<any>;
    };
    os: {
      getUserId(): Promise<string>;
    };
    kitFolder: {
      selectFolder(): Promise<string | null>;
      readKit(folderPath: string): Promise<string | null>;
      writeKit(folderPath: string, json: string): Promise<void>;
      readFile(folderPath: string, filePath: string): Promise<ArrayBuffer | null>;
      writeFile(folderPath: string, filePath: string, data: ArrayBuffer): Promise<void>;
      deleteFile(folderPath: string, filePath: string): Promise<void>;
      listFiles(folderPath: string): Promise<string[]>;
      getRecentFolders(): Promise<string[]>;
      addRecentFolder(folderPath: string): Promise<void>;
    };
