    setLoading(true);
    const adapter = createElectronFolderAdapter(folderPath);
    createFolderKitStore(adapter).then((store) => {
      if (disposed) {
        store.dispose();
        return;
      }
      setKitStore(store);
      setLoading(false);
    });
    return () => {
      disposed = true;
      setKitStore((prev) => {
        if (prev) prev.dispose();
        return undefined;
      });
    };
  }, [folderPath]);

  if (!folderPath) {
    return <StartPage onFolderSelected={setFolderPath} />;
  }

  if (loading || !userId || !kitStore) {
    return <div className="flex h-full w-full items-center justify-center bg-neutral-950 text-white">Loading...</div>;
  }

  return (
    <div className="h-screen w-screen">
      <Sketchpad onWindowEvents={windowEvents} id={userId} kitStore={kitStore} />
    </div>
  );
}

export default App;

createRoot(document.getElementById("root")!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

// #endregion 🔖Renderer

